composants.css:
.pr{display:grid;grid-template-columns:1.1fr .9fr;gap:22px;max-width:1330px;margin:16px auto 0;align-items:center;text-align:left}
.pr-main{background:#f4f6f9;border:1px solid #eaeef2;border-radius:20px;padding:20px 22px}
.pr-main-head{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:13px}
.pr-offer{font-size:24px;font-weight:800;color:#11a9e6}
.pr-price{font-size:24px;font-weight:800;color:#11a9e6}
.pr-price small{font-size:15px;font-weight:700}
.pr-modules{background:#fff;border:1px solid #eef2f6;border-radius:14px;padding:15px 18px}
.pr-mod-title{font-size:14px;font-weight:700;color:#334155;border-bottom:1px solid #e5e9ee;padding-bottom:9px;margin-bottom:13px}
.pr-mod{display:flex;gap:13px;margin-bottom:14px}
.pr-mod:last-child{margin-bottom:0}
.pr-mod-ic{width:44px;height:44px;flex-shrink:0}
.pr-mod-body{flex:1;min-width:0}
.pr-mod-body h4{font-size:14px;font-weight:800;color:#00456d;margin:2px 0 9px}
.pr-feats{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:1fr 1fr;gap:6px 18px}
.pr-feats li{position:relative;padding-left:19px;font-size:11.5px;color:#475569;line-height:1.3}
.pr-feats li::before{content:"✓";position:absolute;left:0;top:0;color:#11a9e6;font-weight:800;font-size:11px}
.pr-apps{display:flex;gap:13px;margin-top:15px}
.pr-app{flex:1;display:flex;align-items:center;gap:10px;background:#fff;border:1px solid #eef2f6;border-radius:13px;box-shadow:0 3px 10px rgba(0,0,0,.05);padding:9px 13px}
.pr-app-ic{width:34px;height:34px;border-radius:9px;background:#f1f6fb;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.pr-app-ic svg{width:19px;height:19px}
.pr-app-ic img{width:22px;height:22px;object-fit:contain}
.pr-app span{font-size:11px;color:#94a3b8;line-height:1.15}
.pr-app b{display:block;font-size:13.5px;color:#00456d;font-weight:800}
.pr-addons-wrap{display:flex;gap:11px;align-items:stretch}
.pr-addons-label{writing-mode:vertical-rl;transform:rotate(180deg);font-size:15px;font-weight:800;color:#c4ccd6;letter-spacing:1.5px;align-self:center;flex-shrink:0}
.pr-addons{flex:1;display:flex;flex-direction:column;gap:9px}
.pr-addon{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:14px;background:#f7f9fb;border:1px solid #eef2f6;border-radius:14px;padding:11px 16px}
.pr-addon.compact{padding:10px 16px}
.pr-addon-ic{width:42px;height:42px;border-radius:11px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.06);display:flex;align-items:center;justify-content:center;gap:2px;flex-shrink:0}
.pr-addon-ic svg{width:22px;height:22px;stroke:#11a9e6;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.pr-addon-ic img{width:24px;height:24px}
.pr-addon-body h4{font-size:13.5px;font-weight:800;color:#00456d;margin:0}
.pr-addon-body p{font-size:11px;color:#6b7280;line-height:1.35;margin:4px 0 0}
.pr-addon-price{font-size:16px;font-weight:800;color:#11a9e6;text-align:right;white-space:nowrap;line-height:1.15}
.pr-addon-price .pr-unit{display:block;font-size:10.5px;font-weight:600;color:#94a3b8}
.pr-free{display:block;color:#0ab38c;font-size:15px}
.pr-was{display:block;color:#b0b8c1;font-weight:600;font-size:10.5px;text-decoration:line-through;margin-top:1px}
.pr-addons.show-opt .pr-optional{display:grid}

.es-calc{background:#fff;border:1px solid #eef2f6;border-radius:20px;box-shadow:0 10px 40px rgba(0,0,0,.10);padding:24px 26px;margin-top:18px;text-align:left;width:1120px;max-width:100%}
.es-calc-top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}
.es-seg{display:inline-flex;background:#f8fafc;border:1px solid #eef2f6;border-radius:11px;padding:4px}
.es-seg button{border:0;background:transparent;padding:9px 20px;border-radius:8px;font-family:inherit;font-size:14px;font-weight:700;color:#6b7280;cursor:pointer;transition:.2s}
.es-seg button.on{background:#fff;color:#11a9e6;box-shadow:0 1px 3px rgba(0,0,0,.08)}
.es-hint{font-size:13px;color:#9ca3af}
.es-slider-row{display:flex;align-items:center;gap:16px;margin-bottom:8px}
.es-slider-row .val{font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;color:#6b7280;text-align:left;white-space:nowrap;font-variant-numeric:tabular-nums}
.es-slider-row .val #esN{font-size:48px;font-weight:700;color:#11a9e6;letter-spacing:0;text-transform:none;margin-right:4px}
#esN .z{visibility:hidden}
.es-calc input[type=range]{-webkit-appearance:none;appearance:none;flex:1;height:6px;border-radius:9999px;background:#eef2f6;outline:none;cursor:pointer}
.es-calc input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:22px;height:22px;border-radius:50%;background:#fff;border:3px solid #11a9e6;box-shadow:0 4px 12px rgba(0,0,0,.08);cursor:pointer}
.es-calc-grid{display:grid;grid-template-columns:1.05fr 1fr;gap:26px;margin-top:12px;align-items:stretch}
.es-col{display:flex;flex-direction:column;height:100%}
.es-calc-grid>div:first-child{order:2}
.es-calc-grid>div:last-child{order:1}
.es-chartwrap svg{width:100%;height:auto;display:block}
.es-legend{display:flex;gap:18px;flex-wrap:wrap;margin-top:8px;font-size:13px;color:#6b7280}
.es-legend .k{display:inline-flex;align-items:center;gap:7px;font-weight:600}
.es-legend .k i{width:16px;height:3px;border-radius:2px;display:inline-block}
.es-eqrow{display:flex;align-items:stretch;gap:9px}
.es-eqc{flex:1;min-width:0;background:#f8fafc;border:1px solid #eef2f6;border-radius:14px;padding:18px 16px}
.es-eqc .k{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.3px;color:#6b7280}
.es-eqc .v{font-size:27px;font-weight:700;color:#00456d;margin-top:9px;line-height:1;font-variant-numeric:tabular-nums}
.es-eqc .v small{font-size:12px;font-weight:600;color:#9ca3af}
.es-eqc.alt{background:linear-gradient(135deg,rgba(15,167,226,.10),rgba(10,179,140,.10));border-color:rgba(17,169,230,.25)}
.es-eqc.alt .v{color:#11a9e6}
.es-op{display:flex;align-items:center;font-size:24px;font-weight:700;color:#c4ccd6}
.es-annual{margin-top:12px;flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}
.es-ro.es-annual .k{margin:0;font-size:15px}
.es-ro.es-annual .v{margin-top:14px;font-size:64px}
.es-ro.es-annual .v small{font-size:26px}
.es-ro{background:#f8fafc;border:1px solid #eef2f6;border-radius:13px;padding:15px}
.es-ro .k{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;color:#6b7280}
.es-ro .v{font-size:28px;font-weight:700;color:#00456d;font-variant-numeric:tabular-nums;margin-top:6px;line-height:1}
.es-ro .v small{font-size:14px;font-weight:600;color:#9ca3af}
.es-ro.hero{background:linear-gradient(135deg,rgba(15,167,226,.10),rgba(10,179,140,.10));border-color:rgba(17,169,230,.25)}
.es-cnote{font-size:12.5px;color:#9ca3af;margin-top:12px;line-height:1.5}

@keyframes barSlideUp { from { opacity: 0; transform: translateY(50px); } to { opacity: 1; transform: translateY(0); } }
@keyframes barFill { from { height: 0; } to { height: 100%; } }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes popIn { from { opacity: 0; transform: scale(0.6); } to { opacity: 1; transform: scale(1); } }
.cost-escalation { display: flex; justify-content: center; align-items: flex-end; gap: 48px; margin: 48px auto 0; max-width: 900px; }
.cost-bar { text-align: center; flex: 1; opacity: 0; }
.cost-bar-visual { border-radius: 16px 16px 0 0; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; padding: 24px 16px; min-width: 180px; position: relative; overflow: hidden; }
.cost-bar-visual::before { content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 0; }
.cost-bar-1 .cost-bar-visual { height: 160px; background: rgba(0,61,121,0.08); }
.cost-bar-1 .cost-bar-visual::before { background: linear-gradient(180deg, #4a90d9 0%, #003d79 100%); }
.cost-bar-2 .cost-bar-visual { height: 240px; background: rgba(10,179,140,0.08); }
.cost-bar-2 .cost-bar-visual::before { background: linear-gradient(180deg, #0ab38c 0%, #078a6c 100%); }
.cost-bar-3 .cost-bar-visual { height: 380px; background: rgba(232,93,74,0.08); }
.cost-bar-3 .cost-bar-visual::before { background: linear-gradient(180deg, #e85d4a 0%, #c0392b 100%); }
.cost-amount { color: #fff; font-size: 32px; font-weight: 700; line-height: 1; position: relative; z-index: 1; opacity: 0; }
.cost-label { color: rgba(255,255,255,0.85); font-size: 13px; margin-top: 6px; position: relative; z-index: 1; opacity: 0; }
.cost-threshold { margin-top: 16px; font-size: 15px; color: #333; font-weight: 600; }
.cost-days { font-size: 13px; color: #777; margin-top: 4px; }
.cost-connector { display: flex; align-items: center; padding-bottom: 80px; opacity: 0; }
.cost-connector-1 .cost-connector-badge { background: linear-gradient(135deg, #003d79, #0ab38c); color: #fff; font-size: 14px; font-weight: 700; padding: 8px 16px; border-radius: 24px; white-space: nowrap; }
.cost-connector-2 .cost-connector-badge { background: linear-gradient(135deg, #0ab38c, #e85d4a); color: #fff; font-size: 14px; font-weight: 700; padding: 8px 16px; border-radius: 24px; white-space: nowrap; }
.cost-connector-line { width: 24px; height: 2px; background: #003d79; }
.slide.active .cost-bar-1 { animation: barSlideUp 0.7s cubic-bezier(0.22,1,0.36,1) 0.2s forwards; }
.slide.active .cost-bar-2 { animation: barSlideUp 0.7s cubic-bezier(0.22,1,0.36,1) 0.5s forwards; }
.slide.active .cost-bar-3 { animation: barSlideUp 0.7s cubic-bezier(0.22,1,0.36,1) 0.8s forwards; }
.slide.active .cost-bar-1 .cost-bar-visual::before { animation: barFill 1s cubic-bezier(0.22,1,0.36,1) 0.4s forwards; }
.slide.active .cost-bar-2 .cost-bar-visual::before { animation: barFill 1s cubic-bezier(0.22,1,0.36,1) 0.7s forwards; }
.slide.active .cost-bar-3 .cost-bar-visual::before { animation: barFill 1s cubic-bezier(0.22,1,0.36,1) 1.0s forwards; }
.slide.active .cost-bar-1 .cost-amount { animation: fadeIn 0.4s ease 1.0s forwards; }
.slide.active .cost-bar-1 .cost-label { animation: fadeIn 0.4s ease 1.1s forwards; }
.slide.active .cost-bar-2 .cost-amount { animation: fadeIn 0.4s ease 1.3s forwards; }
.slide.active .cost-bar-2 .cost-label { animation: fadeIn 0.4s ease 1.4s forwards; }
.slide.active .cost-bar-3 .cost-amount { animation: fadeIn 0.4s ease 1.6s forwards; }
.slide.active .cost-bar-3 .cost-label { animation: fadeIn 0.4s ease 1.7s forwards; }
.slide.active .cost-connector-1 { animation: popIn 0.4s cubic-bezier(0.22,1,0.36,1) 1.2s forwards; }
.slide.active .cost-connector-2 { animation: popIn 0.4s cubic-bezier(0.22,1,0.36,1) 1.6s forwards; }

.case-study-box { max-width: 900px; margin: 32px auto 0; background: #fff; border-radius: 16px; box-shadow: 0 4px 24px rgba(0,0,0,0.08); overflow: hidden; }
.case-header { background: linear-gradient(135deg, #003d79 0%, #0057a8 100%); color: #fff; padding: 28px 36px; display: flex; justify-content: space-between; align-items: center; }
.case-header-left h3 { font-size: 20px; margin: 0 0 6px; font-weight: 700; }
.case-header-left p { font-size: 14px; opacity: 0.8; margin: 0; }
.case-result { text-align: right; }
.case-result-number { font-size: 36px; font-weight: 700; color: #0ab38c; }
.case-result-label { font-size: 13px; opacity: 0.8; }
.case-body { padding: 28px 36px; display: grid; grid-template-columns: 1fr 1fr; gap: 28px; }
.case-section h4 { font-size: 13px; text-transform: uppercase; letter-spacing: 1.5px; color: #003d79; margin: 0 0 12px; }
.case-section p { font-size: 14px; line-height: 1.6; color: #555; margin: 0; }
.case-footer { padding: 20px 36px; background: rgba(10,179,140,0.06); border-top: 1px solid rgba(10,179,140,0.15); display: flex; align-items: center; gap: 12px; }
.case-footer svg { width: 20px; height: 20px; color: #0ab38c; flex-shrink: 0; }
.case-footer p { font-size: 14px; color: #333; margin: 0; font-weight: 600; }

.chain-journey { display: flex; align-items: stretch; gap: 0; width: 100%; max-width: 1220px; margin: 28px auto 0; }
.chain-link { flex: 1; padding: 26px 14px; position: relative; text-align: center; }
.chain-link:first-child { border-radius: 16px 0 0 16px; }
.chain-link:last-child { border-radius: 0 16px 16px 0; }
.chain-number { font-size: 38px; font-weight: 700; opacity: 0.25; line-height: 1; margin-bottom: 6px; }
.chain-verb { font-size: 11px; text-transform: uppercase; letter-spacing: 2.5px; opacity: 0.7; margin-bottom: 6px; }
.chain-title { font-size: 16px; font-weight: 700; margin-bottom: 9px; line-height: 1.3; }
.chain-desc { font-size: 12.5px; opacity: 0.85; line-height: 1.45; }
.chain-offer { font-size: 10.5px; opacity: 0.6; margin-top: 12px; font-style: italic; }
.chain-arrow { display: flex; align-items: center; margin: 0 -12px; z-index: 2; position: relative; }
.chain-arrow svg { width: 24px; height: 24px; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.2)); }

@keyframes ganttBarGrow { from { opacity: 0; transform: scaleX(0); transform-origin: left; } to { opacity: 1; transform: scaleX(1); } }
@keyframes ganttLabelFade { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }
.gantt { width: 100%; max-width: 1180px; margin: 24px auto 0; padding: 0 24px; box-sizing: border-box; }
.gantt-row { display: flex; align-items: center; width: 100%; }
.gantt-row-label { width: 70px; flex: 0 0 70px; font-size: 11px; color: #888; padding-right: 8px; box-sizing: border-box; }
.gantt-month-cell { flex: 1 1 auto; background: linear-gradient(90deg, #4a90d9 0%, #003d79 100%); color: #fff; text-align: center; font-weight: 700; font-size: 15px; letter-spacing: 1px; padding: 10px 0; border-radius: 8px 8px 0 0; }
.gantt-days-grid { flex: 1 1 auto; display: grid; grid-template-columns: repeat(30, 1fr); padding: 8px 0; border-bottom: 1px solid #e0e0e0; min-width: 0; }
.gantt-days-grid span { text-align: center; font-size: 11px; color: #888; min-width: 0; }
.gantt-phase { display: flex; align-items: flex-start; padding-top: 16px; width: 100%; }
.gantt-phase-spacer { width: 70px; flex: 0 0 70px; }
.gantt-track { flex: 1 1 auto; position: relative; height: 52px; min-width: 0; }
.gantt-bar { position: absolute; top: 8px; height: 5px; border-radius: 3px; opacity: 0; }
.gantt-bar::before, .gantt-bar::after { content: ''; position: absolute; top: 50%; transform: translateY(-50%); width: 9px; height: 9px; border-radius: 50%; }
.gantt-bar::before { left: -4px; }
.gantt-bar::after { right: -4px; }
.gantt-bar.bar-1 { background: #4a90d9; }
.gantt-bar.bar-1::before, .gantt-bar.bar-1::after { background: #4a90d9; }
.gantt-bar.bar-2 { background: #4a90d9; }
.gantt-bar.bar-2::before, .gantt-bar.bar-2::after { background: #4a90d9; }
.gantt-bar.bar-3 { background: #0ab38c; }
.gantt-bar.bar-3::before, .gantt-bar.bar-3::after { background: #0ab38c; }
.gantt-label { position: absolute; top: 22px; font-size: 13px; color: #333; line-height: 1.4; opacity: 0; }
.gantt-label strong { color: #003d79; font-weight: 700; }
.slide.active .gantt-bar.bar-1 { animation: ganttBarGrow 0.5s cubic-bezier(0.22,1,0.36,1) 0.3s forwards; }
.slide.active .gantt-bar.bar-2 { animation: ganttBarGrow 0.5s cubic-bezier(0.22,1,0.36,1) 0.6s forwards; }
.slide.active .gantt-bar.bar-3 { animation: ganttBarGrow 0.5s cubic-bezier(0.22,1,0.36,1) 0.9s forwards; }
.slide.active .gantt-label.lbl-1 { animation: ganttLabelFade 0.4s ease 0.6s forwards; }
.slide.active .gantt-label.lbl-2 { animation: ganttLabelFade 0.4s ease 0.9s forwards; }
.slide.active .gantt-label.lbl-3 { animation: ganttLabelFade 0.4s ease 1.2s forwards; }
